<?php
class AluguelDAO {
 public function __construct(private PDO $pdo){}
 public function listar(?int $usuarioId=null): array { $sql="SELECT a.*,u.nome,u.email FROM alugueis a JOIN usuarios u ON u.id=a.usuario_id";if($usuarioId){$s=$this->pdo->prepare($sql." WHERE a.usuario_id=? ORDER BY a.data_reserva DESC");$s->execute([$usuarioId]);return $s->fetchAll();}return $this->pdo->query($sql." ORDER BY a.data_reserva DESC")->fetchAll(); }
 public function buscarPorId(int $id): ?array { $s=$this->pdo->prepare("SELECT a.*,u.nome,u.email FROM alugueis a JOIN usuarios u ON u.id=a.usuario_id WHERE a.id=?");$s->execute([$id]);return $s->fetch()?:null; }
 public function reservar(int $usuarioId,int $livroId): int { $this->pdo->beginTransaction();try{$s=$this->pdo->prepare("SELECT * FROM livros WHERE id=? AND ativo=1 FOR UPDATE");$s->execute([$livroId]);$l=$s->fetch();if(!$l)throw new RuntimeException('Livro não encontrado.');$c=$this->pdo->prepare("SELECT COUNT(*) FROM alugueis WHERE livro_id=? AND status IN ('reservado','ativo')");$c->execute([$livroId]);if((int)$c->fetchColumn()>=(int)$l['estoque_aluguel'])throw new RuntimeException('Não há exemplares disponíveis para aluguel no momento.');$s=$this->pdo->prepare("INSERT INTO alugueis(usuario_id,livro_id,titulo_snapshot,status,valor_aluguel) VALUES(?,?,?,'reservado',?)");$s->execute([$usuarioId,$livroId,$l['titulo'],$l['valor_aluguel']]);$id=(int)$this->pdo->lastInsertId();$this->pdo->commit();return $id;}catch(Throwable $e){$this->pdo->rollBack();throw $e;} }
 public function atualizarStatus(int $id,string $status): bool { $a=$this->buscarPorId($id);if(!$a)return false;if($status==='ativo' && $a['status']==='reservado')return $this->pdo->prepare("UPDATE alugueis SET status='ativo',data_retirada=NOW(),data_prevista_devolucao=DATE_ADD(CURDATE(),INTERVAL 7 DAY) WHERE id=?")->execute([$id]);if($status==='devolvido' && $a['status']==='ativo')return $this->pdo->prepare("UPDATE alugueis SET status='devolvido',data_devolucao=NOW() WHERE id=?")->execute([$id]);if($status==='cancelado' && $a['status']==='reservado')return $this->pdo->prepare("UPDATE alugueis SET status='cancelado' WHERE id=?")->execute([$id]);return false; }
 public function editar(int $id,array $d): bool { return $this->atualizarStatus($id,(string)($d['status']??'')); }
 public function deletar(int $id): bool { return $this->pdo->prepare("DELETE FROM alugueis WHERE id=?")->execute([$id]); }
}
